command:
$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-05. Two questions raised by the compat proof, answered before going further.
#
# 1. The store shrank. Before native Ollama first touched D:\HermesData\ollama there were 25 blobs /
#    10,360,082,334 bytes; after, 21 / 10,360,071,891. Ollama prunes blobs no manifest references on
#    startup (OLLAMA_NOPRUNE defaulted false). Four files went. This lane has to say exactly which,
#    and prove the surviving set is exactly the referenced set -- not assert that "only orphans" went
#    because that is the comfortable answer.
# 2. Ollama v0.32.15's cuda_v12 runner emits PTX this driver cannot load. Find which published
#    versions could, by inspecting what CUDA toolkit each ships rather than by guessing at tags.

Write-Output '--- D-BLOBS-NOW ---'
Get-ChildItem 'D:\HermesData\ollama\models\blobs' -File | Sort-Object Name | ForEach-Object { "BLOB $($_.Name) $($_.Length)" }

Write-Output '--- REFERENCED-SET ---'
$mdir = 'D:\HermesData\ollama\models\manifests'
$refs = @{}
Get-ChildItem $mdir -Recurse -File | ForEach-Object {
    $j = Get-Content $_.FullName -Raw | ConvertFrom-Json
    $name = $_.FullName.Substring($mdir.Length + 1)
    if ($j.config.digest) { $refs[($j.config.digest -replace ':', '-')] = 1 }
    foreach ($l in $j.layers) { $refs[($l.digest -replace ':', '-')] = 1 }
    Write-Output "manifest=$name config=$($j.config.digest) layers=$(($j.layers | ForEach-Object { $_.digest }) -join ' ')"
}
Write-Output "unique_referenced=$($refs.Count)"
$have = @{}
Get-ChildItem 'D:\HermesData\ollama\models\blobs' -File | ForEach-Object { $have[$_.Name] = $_.Length }
Write-Output "present=$($have.Count)"
Write-Output "referenced_but_missing=$((@($refs.Keys | Where-Object { -not $have.ContainsKey($_) })) -join ',')"
Write-Output "present_but_unreferenced=$((@($have.Keys | Where-Object { -not $refs.ContainsKey($_) })) -join ',')"
$sum = 0; $refs.Keys | ForEach-Object { if ($have.ContainsKey($_)) { $sum += $have[$_] } }
Write-Output "referenced_bytes=$sum"

Write-Output '--- G-STORE-UNCHANGED ---'
$g = Get-ChildItem 'G:\HermesData\ollama\models\blobs' -File -ErrorAction SilentlyContinue | Measure-Object -Sum Length
Write-Output "G blobs=$($g.Count) bytes=$($g.Sum)"

Write-Output '--- RELEASES ---'
try {
    $all = @()
    foreach ($page in 1..4) {
        $r = Invoke-WebRequest -Uri "https://api.github.com/repos/ollama/ollama/releases?per_page=100&page=$page" -UseBasicParsing -TimeoutSec 60
        $all += ($r.Content | ConvertFrom-Json)
    }
    Write-Output "release_count=$($all.Count)"
    $all | Where-Object { -not $_.prerelease } | Select-Object -First 60 | ForEach-Object {
        $z = $_.assets | Where-Object { $_.name -eq 'ollama-windows-amd64.zip' }
        "REL $($_.tag_name) published=$($_.published_at) zip_bytes=$($z.size)"
    }
} catch { Write-Output "releases_ERR=$($_.Exception.Message)" }
Write-Output '--- RC ---'
